1	% Standalone TikZ: Normalization-Induced Routing Collapse Mechanism
2	% Usage: \input{figures/tikz_collapse_mechanism.tex} inside a figure environment
3	%
4	% Academic-style two-panel figure modeled on the gemini-academic-viz reference
5	% (figures/talk/collapse_mechanism_v2.png). Conventions:
6	%   * white-fill panels with thin colored strokes (no solid color fills)
7	%   * desaturated muted palette (dusty blue / sage / brick / ochre)
8	%   * single dominant stroke weight (~0.7pt); only highlighted E1 thicker
9	%   * thin line arrows with small triangular arrowheads (no block arrows)
10	%   * plain black caption text (no colored captions)
11	%   * lowercase bold (a) / (b) panel labels per NeurIPS convention
12	%
13	% Routing pattern: all routing arrows emerge BELOW the panel stack and fan
14	% out to the experts. Color encoding (blue / green / red / ochre) carries the
15	% waveform-to-expert identity, so no arrows need to cross or pass through
16	% any panel.
17	
18	\definecolor{cmDustyBlue}{RGB}{74,111,165}
19	\definecolor{cmSageGreen}{RGB}{107,142,90}
20	\definecolor{cmBrickRed}{RGB}{168,74,74}
21	\definecolor{cmOchre}{RGB}{184,137,62}
22	\definecolor{cmGhost}{RGB}{176,176,176}
23	
24	\begin{tikzpicture}[
25	    wavepanel/.style={rectangle, draw=#1, fill=white, line width=0.7pt,
26	        rounded corners=1.5pt, minimum width=4cm, minimum height=0.65cm,
27	        inner sep=2pt},
28	    wavepanelgray/.style={rectangle, draw=cmGhost, fill=white, line width=0.6pt,
29	        rounded corners=1.5pt, minimum width=4cm, minimum height=0.65cm,
30	        inner sep=2pt},
31	    expert/.style={rectangle, draw=#1, fill=white, line width=0.7pt,
32	        rounded corners=2pt, minimum width=0.85cm, minimum height=0.5cm,
33	        font=\scriptsize\bfseries, text=#1},
34	    expertactive/.style={rectangle, draw=cmBrickRed, fill=white, line width=1.0pt,
35	        rounded corners=2pt, minimum width=0.85cm, minimum height=0.5cm,
36	        font=\scriptsize\bfseries, text=cmBrickRed},
37	    expertghost/.style={rectangle, draw=cmGhost, fill=white, line width=0.5pt,
38	        rounded corners=2pt, minimum width=0.85cm, minimum height=0.5cm,
39	        font=\scriptsize, text=cmGhost},
40	    arr/.style={-{Stealth[length=1.7mm,width=1.3mm]}, line width=0.65pt, #1},
41	    normarr/.style={-{Stealth[length=2mm,width=1.5mm]}, line width=0.7pt, black!75},
42	    panellabel/.style={font=\small\bfseries, anchor=west, text=black},
43	    caption/.style={font=\small, anchor=north, text=black},
44	]
45	
46	% ============================================================
47	% (a) Raw input space
48	% ============================================================
49	\node[panellabel] at (0.0, 5.10) {(a) Raw input space};
50	
