\node[wavepanelgray] (n4) at (10.0, 2.15) {};

\foreach \y in {4.40, 3.65, 2.90, 2.15} {
    \draw[cmGhost, line width=0.55pt]
        plot[domain=8.20:11.80, samples=80, smooth]
        ({\x},{\y+0.10*sin(deg(3.0*(\x-10.0)))});
}

% Experts: only E1 highlighted, E2-E4 ghosted
\node[expertactive] (re1) at (8.50, 1.20) {E1};
\node[expertghost]  (re2) at (9.50, 1.20) {E2};
\node[expertghost]  (re3) at (10.50, 1.20) {E3};
\node[expertghost]  (re4) at (11.50, 1.20) {E4};

% Convergent ghost arrows: four arrows below the panel stack, all pointing
% diagonally to E1 — the visual signature of routing collapse.
\draw[arr=cmGhost] (8.50, 1.83) -- (re1.north);
\draw[arr=cmGhost] (9.50, 1.83) -- ([xshift=0.07cm]re1.north);
\draw[arr=cmGhost] (10.50, 1.83) -- ([xshift=0.14cm]re1.north);
\draw[arr=cmGhost] (11.50, 1.83) -- ([xshift=0.21cm]re1.north);

\node[caption] at (10.0, 0.60) {Collapse: $H = 0.000$};

\end{tikzpicture}

